OLD_OPEN_STATUSES = ["nou", "sunat", "raspuns", "in_lucru"]


def to_three_statuses(apps, schema_editor):
    """Every open status becomes "potential"; lost opportunities lose their seller."""
    Opportunity = apps.get_model("oportunitati", "Opportunity")
    Opportunity.objects.filter(status__in=OLD_OPEN_STATUSES).update(status="potential")
    Opportunity.objects.filter(status="pierduta").update(owner=None)


def back_to_old_statuses(apps, schema_editor):
    Opportunity = apps.get_model("oportunitati", "Opportunity")
    Opportunity.objects.filter(status="potential").update(status="in_lucru")
    # The old schema needs an owner: whoever wrote the last note, or created the opportunity.
    for opportunity in Opportunity.objects.filter(owner__isnull=True):
        last = opportunity.notes.exclude(author=None).order_by("-created_at").first()
        opportunity.owner_id = last.author_id if last else opportunity.created_by_id
        opportunity.save(update_fields=["owner"])


